#include <Eigen/Dense>
#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace Eigen;

// Constant Strain Triangle (CST) membrane stiffness, 6x6 (2 DOF per node)
// nodes: 3x2 matrix of (x,y), E, nu, t
Matrix<double,6,6> cst_stiffness(const Matrix<double,3,2>& xy, double E, double nu, double t) {
    // Plane stress D matrix
    Matrix3d D;
    double c = E/(1.0 - nu*nu);
    D << c,      c*nu,   0.0,
         c*nu,   c,      0.0,
         0.0,    0.0,    c*(1.0-nu)/2.0;

    // Area
    double x1=xy(0,0), y1=xy(0,1);
    double x2=xy(1,0), y2=xy(1,1);
    double x3=xy(2,0), y3=xy(2,1);
    double A2 = (x2-x1)*(y3-y1) - (x3-x1)*(y2-y1); // 2*Area
    double A = 0.5*A2;

    // B matrix (3x6)
    Matrix<double,3,6> B;
    double b1 = y2-y3, b2 = y3-y1, b3 = y1-y2;
    double c1 = x3-x2, c2 = x1-x3, c3 = x2-x1;
    B << b1, 0, b2, 0, b3, 0,
         0, c1, 0, c2, 0, c3,
         c1, b1, c2, b2, c3, b3;
    B /= A2;

    Matrix<double,6,6> K = t * A * (B.transpose() * D * B);
    return K;
}

int main() {
    // Test case
    double E = 200e9, nu = 0.3, t = 0.01;
    // Nodes: (0,0),(2,0),(2,1.5),(0,1.5)
    Matrix<double,4,2> nodes;
    nodes << 0,0, 2,0, 2,1.5, 0,1.5;

    // Mapping table M (1-based in Fortran): triangles
    // Triangle I:   nodes 1,2,4
    // Triangle II:  nodes 2,3,1
    // Triangle III: nodes 3,4,2
    // Triangle IV:  nodes 4,1,3
    int M[12] = {1,2,4, 2,3,1, 3,4,2, 4,1,3};

    Matrix<double,8,8> K = Matrix<double,8,8>::Zero();

    for (int j = 0; j < 4; ++j) {
        int n0 = M[3*j+0]-1;
        int n1 = M[3*j+1]-1;
        int n2 = M[3*j+2]-1;
        Matrix<double,3,2> xy;
        xy << nodes(n0,0), nodes(n0,1),
              nodes(n1,0), nodes(n1,1),
              nodes(n2,0), nodes(n2,1);
        Matrix<double,6,6> kt = cst_stiffness(xy, E, nu, t);
        int idx[3] = {n0, n1, n2};
        for (int a=0;a<3;++a)
            for (int b=0;b<3;++b)
                for (int da=0;da<2;++da)
                    for (int db=0;db<2;++db)
                        K(2*idx[a]+da, 2*idx[b]+db) += kt(2*a+da, 2*b+db);
    }

    // Print JSON
    std::cout << std::setprecision(10);
    std::cout << "{\"stiffness_matrix\":[";
    for (int i=0;i<8;++i){
        std::cout << "[";
        for (int j=0;j<8;++j){
            std::cout << std::scientific << K(i,j);
            if (j<7) std::cout << ",";
        }
        std::cout << "]";
        if (i<7) std::cout << ",";
    }
    std::cout << "]}" << std::endl;
    return 0;
}
